                        self.pending = nil
                    } else if let result, result.isFinal {
                        self.pending?.resume(returning: result.bestTranscription.formattedString)
                        self.pending = nil
                    }
                }
            }
        } onCancel: {
            currentTask?.cancel()
        }
    }
}

