                    guard let data else { return }
                    do {
                        continuation.resume(returning: try JSONDecoder().decode(ValidationResult.self, from: data))
                    } catch {
                        continuation.resume(throwing: error)
                    }
                }
                task?.resume()
            }
        } onCancel: {
            task?.cancel()
        }
    }
}

