import CoreLocation

enum LocatorError: Error { case alreadyRunning }

@MainActor
final class OneShotLocator: NSObject, CLLocationManagerDelegate {
    private let manager = CLLocationManager()
    private var continuation: CheckedContinuation<CLLocation, Error>?

    override init() {
        super.init()
        manager.delegate = self
    }

    func locate() async throws -> CLLocation {
        guard continuation == nil else { throw LocatorError.alreadyRunning }
        return try await withTaskCancellationHandler {
            try await withCheckedThrowingContinuation { continuation in
                self.continuation = continuation
                manager.requestLocation()
            }
        } onCancel: {
            Task { @MainActor in
                self.manager.stopUpdatingLocation()
                self.finish(.failure(CancellationError()))
            }
        }
    }

    private func finish(_ result: Result<CLLocation, Error>) {
        continuation?.resume(with: result)
        continuation = nil
    }

    nonisolated func locationManager(_ manager: CLLocationManager, didUpdateLocations locations: [CLLocation]) {
        let result: Result<CLLocation, Error> = locations.last.map { .success($0) } ?? .failure(CLError(.locationUnknown))
        Task { @MainActor in self.finish(result) }
    }

    nonisolated func locationManager(_ manager: CLLocationManager, didFailWithError error: Error) {
        Task { @MainActor in self.finish(.failure(error)) }
    }
}

import Foundation

actor RPCChannel {
    private var pending: [UUID: CheckedContinuation<Data, Error>] = [:]
    private let transport: MessageTransport

    init(transport: MessageTransport) {
        self.transport = transport
    }

    func send(_ method: String, params: Data) async throws -> Data {
        let id = UUID()
        return try await withTaskCancellationHandler {
            try await withCheckedThrowingContinuation { continuation in
                pending[id] = continuation
                transport.post(id: id, method: method, params: params)
            }
        } onCancel: {
            Task { await self.fail(id, with: CancellationError()) }
        }
    }

    func receive(id: UUID, payload: Data) {
        pending.removeValue(forKey: id)?.resume(returning: payload)
    }

    func fail(_ id: UUID, with error: Error) {
        pending.removeValue(forKey: id)?.resume(throwing: error)
    }
}

import Foundation

@MainActor
final class TokenRefresher {
    private let authClient: LegacyAuthClient
    private var waiters: [UUID: CheckedContinuation<AuthToken, Error>] = [:]
    private var inFlight: LegacyAuthClient.Operation?

    init(authClient: LegacyAuthClient) {
        self.authClient = authClient
    }

    /// Concurrent callers share one refresh; each waiter is stored under its own id.
    func validToken() async throws -> AuthToken {
        let id = UUID()
        return try await withTaskCancellationHandler {
            try await withCheckedThrowingContinuation { continuation in
                waiters[id] = continuation
                startRefreshIfNeeded()
            }
        } onCancel: {
            Task { @MainActor in self.cancelWaiter(id) }
        }
    }

    private func startRefreshIfNeeded() {
        guard inFlight == nil else { return }
        inFlight = authClient.refresh { [weak self] result in
            Task { @MainActor in self?.complete(with: result) }
        }
    }

    private func complete(with result: Result<AuthToken, Error>) {
        inFlight = nil
        let pending = waiters
        waiters.removeAll()
        for continuation in pending.values {
            continuation.resume(with: result)
        }
    }

    private func cancelWaiter(_ id: UUID) {
        waiters.removeValue(forKey: id)?.resume(throwing: CancellationError())
        if waiters.isEmpty {
            inFlight?.cancel()
            inFlight = nil
        }
    }
}

import Network

final class NetworkStatusMonitor {
    private let monitor = NWPathMonitor()
    private let queue = DispatchQueue(label: "network-monitor")
    private var continuation: AsyncStream<NWPath.Status>.Continuation?

    lazy var updates: AsyncStream<NWPath.Status> = AsyncStream { continuation in
        self.continuation = continuation
        continuation.onTermination = { [weak self] _ in
            self?.monitor.cancel()
        }
        monitor.pathUpdateHandler = { path in
            continuation.yield(path.status)
        }
        monitor.start(queue: queue)
    }
}

