private var replies: [Int: CheckedContinuation<Data, Error>] = [:]
private var nextID = 0

func request(_ name: String) async throws -> Data {
    nextID += 1
    let id = nextID
    return try await withTaskCancellationHandler {
        try await withCheckedThrowingContinuation { continuation in
            replies[id] = continuation
            transport.send(name, id: id)
        }
    } onCancel: {
        Task { @MainActor in
            self.replies.removeValue(forKey: id)?.resume(throwing: CancellationError())
        }
    }
}

